// Експертний контент: одяг Butterfly — футболки, костюми, куртки й олімпійки, шорти й
// спідниця, шкарпетки, напульсники (партія 5). Формат і правила — як у gearExpert.ts: лише
// факти виробника, без підписаних тренером оцінок і «думки експерта».
//
// ⚠️ ДЖЕРЕЛА (звірено 19.10.2026, кожну модель — ще й по фото: наше фото ↔ фото виробника):
//  • teessport.com — фірмові описи Butterfly в архіві дилера (матеріал, деталі, кольори);
//  • butterfly-adria.com — офіційний дистрибʼютор Butterfly (Abiko, Ikoma, Kariya, Nagano,
//    Nagoya, Puren, Puro, Saijo, Sutairu, Tosy, Toyama, Apego, Uruma, Chiara, Kijun);
//  • vsenastolnitenis.cz — дилер Butterfly (Чехія), описи колекцій і склад: Higo, Izumo, Kisa,
//    Tori, Toc, Daito, Meranji, Antei, Yasu Cotton, Riso, Niiza, Otaru, Anjo, Streak, Hachimaki
//    (партія 6, 20.10.2026; пошук: /cz/list-all-products-29452?keyword=…, не частіше 1 запиту/3 с).
// Свідомо НЕ відкрито: японські моделі без ціни (Elistar, Infiria, Lunaseam…) і моделі без збігу
// фото чи опису (Iwagy, Yaizu, Kariya шорти, 70th, Ukraine, Suribu, Koba, кепка 1950).
// Кольори в текстах — ті, у яких модель випускав Butterfly; наявність кольору й розміру —
// на картці (вибір варіанта), її тут не обіцяємо.
import type { ComparisonRow, ExpertEntry } from "./expert";

type L = { ua: string; ru: string };
const t = (ua: string, ru: string): L => ({ ua, ru });
const qa = (qua: string, qru: string, aua: string, aru: string) => ({ q: t(qua, qru), a: t(aua, aru) });
const sec = (tua: string, tru: string, bua: string, bru: string) => ({ title: t(tua, tru), body: t(bua, bru) });
const row = (slug: string, model: string, c1: L, c2: L, c3: L, fit: L): ComparisonRow => ({
  slug,
  model,
  cells: { c1, c2, c3 },
  fit,
});
type Body = Omit<ExpertEntry, "comparison" | "comparisonTitle" | "comparisonCols">;

const MEN = t("Чоловічий", "Мужской");
const WOMEN = t("Жіночий", "Женский");

